/* Six complete journeys share a merchant-controlled workflow. */
CASES.incident={...CASES.recovery,title:'Find what is behind a sudden sales drop',short:'Campaign diagnosis',campaign:'Weekend launch · incident review',tag:'Connected investigation',color:'blue',channel:'Campaign + payment health + orders + consent',intro:'Ananya, Weekend launch lost paid conversion during a payment incident. Before changing the campaign or adding a discount, I can compare campaign cohorts, payment health, inventory and later orders.',story:FUTURES.incident.pain,pain:FUTURES.incident.pain,signal:'4 sources to compare',impact:'84 affected shoppers · 38 contactable after checks',finding:'The payment incident fits the timing, and current stock is available. 32 shoppers later paid; of 52 still unpaid, 38 have recorded consent. Weak campaign copy is not established. A bounded retry is worth evaluating after a fresh health check.',steps:[['Evidence agent','Compare campaign and incident timing','Matched cohort overlaps the affected payment route; association is not proof of intent.'],['Order agent','Check stock and later payments','Stock is available in sample records; 32 later-paid shoppers excluded.'],['Policy agent','Check consent and contact history','38 eligible shoppers remain. A fresh check is required before dispatch.']],model:FUTURES.incident.why,source:'Merchant campaign ID → payment attempts and health → current inventory and order status → consent history → assigned reminder → paid outcomes and refunds.',guard:FUTURES.incident.limits+' Recheck all eligibility immediately before dispatch. If health or stock is uncertain, pause.',evidence:[['Affected shoppers','84'],['Already paid','32 · Excluded'],['Still unpaid','52'],['Contactable after consent check','38'],['Connected evidence sources','4 · Simulated']],choices:[['sms','Test one reminder for eligible shoppers','No new discount; refresh payment, stock and consent'],['handoff','Keep customer contact off','Prepare an internal investigation brief']]};
CASES.economics={...CASES.cost,title:'Find where campaign profit is disappearing',short:'Profit diagnosis',campaign:'Loyalty growth · margin review',tag:'Connected investigation',color:'purple',channel:'Campaign + funding + costs + refunds',intro:'Ananya, more rewards are being redeemed, but contribution is weaker. I can compare reward funding, product costs and returns before proposing a change. We may need to wait for mature data.',story:FUTURES.economics.pain,pain:FUTURES.economics.pain,signal:'4 sources to reconcile',impact:'₹350 per retained order after today’s reward',finding:'The sample funding and cost records agree: ₹500 contribution before the merchant-funded ₹150 reward. A separate ₹75 variant would leave ₹425 per retained order. Some recent returns are unresolved; conversion and net contribution still need a controlled comparison.',steps:[['Funding analyst','Reconcile reward liability','₹150 is merchant-funded in the sample agreement.'],['Cost analyst','Join costs and refund maturity','₹500 before reward; recent refund outcomes remain unresolved.'],['Experiment planner','Compare a smaller reward with waiting','A ₹75 variant meets a ₹400 retained-order floor under the sample cost assumptions.']],question:'How would you like to proceed with the uncertainty?',why:'I can draft a guarded experiment, or hold changes until the return cohort matures.',choices:[['400','Draft a test with a ₹400 floor','Separate ₹75 reward; mature refunds gate any rollout'],['handoff','Wait for mature return data','Prepare a reconciliation brief; no reward changes']],model:FUTURES.economics.why,source:'Assigned customer → order → funding agreement and redemption ledger → item costs → fulfilment and payment costs → refunds → retained contribution.',guard:FUTURES.economics.limits+' Preserve issued rewards, create a separate variant and approve a worst-case budget.',evidence:[['Contribution before reward','₹500 / retained order'],['Merchant-funded reward','₹150'],['After current reward','₹350'],['Proposed separate reward','₹75 → ₹425'],['Recent return cohort','Not mature · No scaling']]};
const JOURNEYS={clarity:{icon:'gift',label:'Offer clarity',line:'Help shoppers understand the benefit before checkout.',sources:['Campaign copy','Offer terms','Checkout','Payments'],confidence:'A testable hypothesis',decision:'Change the presentation, keep the offer unchanged'},recovery:{icon:'bolt',label:'Payment recovery',line:'Help interested shoppers retry without extra discounts.',sources:['Payment health','Orders','Consent'],confidence:'Eligibility checked in sample records',decision:'One reminder to a limited, consented audience'},cost:{icon:'wallet',label:'Incentive efficiency',line:'Find whether a smaller reward earns more contribution.',sources:['Rewards','Funding','Cost sheet'],confidence:'Cost arithmetic verified; response unknown',decision:'Approve a new variant, preserve existing rewards'},repeat:{icon:'clock',label:'Repeat-purchase timing',line:'Reach past customers at a more relevant moment.',sources:['Purchases','Consent','Contact history'],confidence:'Timing hypothesis; holdout required',decision:'Choose recency, cap the audience and contact once'},incident:{icon:'link',label:'Campaign diagnosis',line:'Compare payment, stock and campaign explanations.',sources:['Campaign','Health','Inventory','Consent'],confidence:'Several sources; cause remains uncertain',decision:'Approve a bounded retry or an internal brief'},economics:{icon:'chart',label:'Profit diagnosis',line:'Check rewards, costs and returns before changing spend.',sources:['Campaign','Funding','Costs','Refunds'],confidence:'Cost evidence available; returns still maturing',decision:'Approve a guarded test or wait for mature data'}};
const STORAGE='campaign-outcome-demo-v6';let saveTimer;
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({sessions,current,page,tab}))}catch(e){}}
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved&&saved.sessions){for(const [id,a] of Object.entries(saved.sessions)){if(!CASES[id]||!Array.isArray(a.messages))continue;sessions[id]=a;if(a.run?.status==='running')a.run.status='paused'}if(CASES[saved.current])current=saved.current;page=['case','experiments'].includes(saved.page)?saved.page:'overview';tab=['chat','evidence','plan','results','activity'].includes(saved.tab)?saved.tab:'chat'}}catch(e){}
const priorRender=render,priorRefresh=refreshChat,priorEdit=edit,priorBegin=begin,priorChoose=choose,priorModal=modal,priorDone=doneCard,priorReview=reviewCard,priorResults=resultTab,priorEvidence=evidence;
function lifecycle(a){if(!a||a.stage==='intro')return {name:'Ready to explore',tone:''};if(a.stage==='stopped')return {name:'Stopped',tone:''};if(a.run?.status==='blocked')return {name:'Needs connection',tone:'amber'};if(a.run?.status==='paused')return {name:'Paused safely',tone:'amber'};if(a.stage==='done'&&a.paused)return {name:'Test paused',tone:'amber'};if(a.results)return {name:'Sample outcome ready',tone:'green'};if(a.stage==='done')return {name:a.choice==='handoff'?'Brief ready':a.paused?'Test paused':'Test scheduled',tone:'green'};if(a.stage==='review')return {name:'Needs your approval',tone:'amber'};if(a.stage==='question')return {name:'Needs your input',tone:'blue'};return {name:'Agent working',tone:'blue'}}
function journeyCard(id){let c=CASES[id],j=JOURNEYS[id],a=sessions[id],st=lifecycle(a);return `<article class="panel journey-card"><div class="between"><div class="journey-icon">${icon(j.icon)}</div>${pill(st.name,st.tone)}</div><h3>${j.label}</h3><p>${j.line}</p><div class="journey-signal"><strong>${c.signal}</strong><small>${c.impact}</small></div><div class="source-chips">${j.sources.map(x=>`<span>${x}</span>`).join('')}</div><div class="cardfoot"><span class="fine">${id==='incident'||id==='economics'?'Extended concept':'Core scenario'}</span>${btn(a&&a.stage!=='intro'?'Continue journey '+icon('arrow'):'Explore '+icon('arrow'),`openCase('${id}')`,'primary')}</div></article>`}
overview=function(){let values=Object.values(sessions),ready=values.filter(a=>['question','review'].includes(a.stage)).length,active=values.filter(a=>a.stage==='done'&&a.choice!=='handoff'&&!a.paused).length;return `<div class="crumb">Engage / Campaign outcomes</div>${heading('Good morning, Ananya','Let’s turn your campaign signals into a confident next step.',btn('My experiments '+icon('arrow'),"showExperiments()"))}<section class="welcome-panel"><div><div class="eyebrow">Your campaign assistant</div><h2>Find the friction.<br>Choose the next step with confidence.</h2><p>I’ll connect the evidence, explain the trade-offs and prepare a plan. You decide what changes.</p><div class="trust-inline"><span>✓ Review before action</span><span>✓ Clear limits</span><span>✓ Pause or stop anytime</span></div></div><div class="welcome-status"><strong>6</strong><span>complete scenario journeys</span><div><b>${ready}</b> awaiting your decision <br><b>${active}</b> scheduled in this demo</div></div></section><section class="start-strip"><div class="journey-icon">${icon('spark')}</div><div><strong>First visit? Start with offer clarity.</strong><p>One complete example of investigate → decide → approve → measure. All six scenarios use the same familiar flow.</p></div>${btn(sessions.clarity?.stage&&sessions.clarity.stage!=='intro'?'Continue offer clarity':'Start guided journey',"openCase('clarity')",'primary')}</section><div class="section-intro"><h2>Your opportunities</h2><p>Choose the situation you want to understand. Every card opens a complete interactive journey.</p></div><div class="opportunity-grid">${['clarity','recovery','cost','repeat'].map(journeyCard).join('')}</div><div class="section-intro"><h2>Bring more evidence into the decision</h2><p>Two extended concepts with the same review, approval, execution and outcome flow. Proposed data connections are simulated.</p></div><div class="opportunity-grid">${['incident','economics'].map(journeyCard).join('')}</div><section class="foundation-note"><span>${icon('info')}</span><p><strong>Built on the Engage direction.</strong> Engage already offers campaigns, offers and retention tools. This concept adds joined investigation and controlled outcome measurement.</p><button class="textbtn" onclick="modal('difference')">What we’re extending</button></section>`};
sidebar=function(){return `<div class="brand"><div class="avatar">SH</div><div><strong>Sunday Home</strong><small>Ananya Shah · Owner</small></div></div><div class="navlabel">ENGAGE WORKSPACE</div><button class="nav ${page==='overview'?'active':''}" onclick="goHome()">${icon('home')}<span>Opportunities</span></button><button class="nav ${page==='case'?'active':''}" onclick="openCase(current)">${icon('spark')}<span>Personal assistant</span></button><button class="nav ${page==='experiments'?'active':''}" onclick="showExperiments()">${icon('chart')}<span>My experiments</span></button><div class="navlabel">YOUR CONTROLS</div><button class="nav" onclick="modal('connections')">${icon('link')}<span>Data & connections</span></button><button class="nav" onclick="modal('permissions')">${icon('shield')}<span>Permissions</span></button><button class="nav" onclick="modal('studio')">${icon('spark')}<span>Agent roles</span></button><div class="bottom"><div class="panel" style="padding:15px;background:#eff6f2"><strong style="font-size:13px">Your decisions stay yours</strong><p style="font-size:12px;margin-top:6px">Drafts need approval. Changes need a fresh review.</p><span class="fine">Demo progress saved on this browser.</span></div></div>`};
function stageIndex(a){if(a.results)return 4;return {intro:0,investigating:0,question:1,review:2,executing:3,done:3,stopped:0}[a.stage]??0}
function progressRail(){let i=stageIndex(A());return `<div class="journey-rail" aria-label="Journey progress">${['Investigate','Your decision','Review & approve','Execute','Measure & learn'].map((x,n)=>`<div class="${n<i?'complete':n===i?'current':''}"><span>${n<i?'✓':n+1}</span><b>${x}</b></div>`).join('')}</div>`}
caseView=function(){let c=C(),a=A();return `<div class="crumb"><button onclick="goHome()">All opportunities</button> / ${safe(c.campaign)}</div>${heading(JOURNEYS[current].label,JOURNEYS[current].line,`<label class="case-picker">Switch scenario <select aria-label="Choose example" onchange="openCase(this.value)">${Object.entries(JOURNEYS).map(([id,j])=>`<option value="${id}" ${id===current?'selected':''}>${j.label}</option>`).join('')}</select></label>`)}${progressRail()}<div class="tabs case-tabs" role="tablist" aria-label="Opportunity workspace">${[['chat','Personal assistant'],['evidence','Evidence & journey'],['plan','Action plan'],['results','Results'],['activity','Activity']].map(([id,s])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" onclick="switchTab('${id}')">${s}</button>`).join('')}</div>${tab==='chat'?chat():tab==='evidence'?evidence():tab==='plan'?planTab():tab==='results'?resultTab():activityTab()}`};
context=function(){let c=C(),a=A(),j=JOURNEYS[current],st=lifecycle(a);return `<aside class="case-context"><div class="panel"><div class="eyebrow">Your opportunity</div><h3>${c.campaign}</h3><div class="contextitem"><span class="fine">WHAT WE NOTICED</span><strong>${c.signal}</strong><p>${c.impact}</p></div><div class="contextitem"><span class="fine">EVIDENCE QUALITY</span><strong>${j.confidence}</strong><p>${a.connected?'Demo sources available':'A required source is unavailable'}</p><button class="textbtn spaced" onclick="switchTab('evidence')">Inspect the evidence →</button></div><div class="contextitem"><span class="fine">CURRENT STATUS</span><strong id="context-status">${st.name}</strong></div></div><div class="panel sectionspace"><h3>You’re in control</h3><p id="permission-status" class="spaced">${a.approved?'Only this approved revision can run.':'I can investigate and draft. Your approval is required to act.'}</p><p class="fine spaced">${j.decision}</p><button class="textbtn spaced" onclick="modal('permissions')">Review permissions & limits</button></div></aside>`};
function showExperiments(){page='experiments';render()}
function experiments(){const ids=Object.keys(sessions).filter(id=>CASES[id]&&sessions[id].stage!=='intro');return `<div class="crumb">Engage / My experiments</div>${heading('Your work, all in one place','Return to a decision, inspect an approved plan or pause future work.',btn('Explore opportunities','goHome()','primary'))}${ids.length?`<div class="experiment-list">${ids.map(id=>{let a=sessions[id],c=CASES[id],st=lifecycle(a);return `<section class="panel experiment-row"><div class="journey-icon">${icon(JOURNEYS[id].icon)}</div><div><h3>${JOURNEYS[id].label}</h3><p>${c.campaign}</p><small class="fine">${a.approval?'Approved cap: '+a.approval.cap+' · '+(a.choice==='handoff'?'Internal brief only':'Versioned plan'):'No execution approval yet'}</small></div>${pill(st.name,st.tone)}${btn('Continue',`openCase('${id}')`)}${a.stage==='done'&&a.choice!=='handoff'?btn(a.paused?'Resume':'Pause',`manageSchedule('${id}')`):''}</section>`}).join('')}</div>`:`<section class="panel empty"><div class="journey-icon" style="margin:0 auto 15px">${icon('chart')}</div><h2>Your first experiment starts with a question.</h2><p class="spaced">Explore an opportunity. Your investigation, decisions and approved plan will appear here.</p>${btn('Explore offer clarity',"openCase('clarity')",'primary spaced')}</section>`}<p class="fine spaced">Saved locally in this browser. All records, approvals and outcomes are fictional. Reset clears demo progress.</p>`}
function manageSchedule(id){let a=session(id);a.paused=!a.paused;log(a.paused?'Merchant paused future exposure.':'Merchant resumed the approved schedule.',id);render()}
render=function(){if(page==='experiments'){$('sidebar').innerHTML=sidebar();$('main').innerHTML=experiments();$('journey').innerHTML='';history.replaceState(null,'','#experiments');window.scrollTo(0,0)}else{if(page==='future'){current=futureId;page='case';tab='chat';if(!A().messages.length)bot(C().intro)}priorRender()}persist()};
refreshChat=function(){priorRefresh();let rail=document.querySelector('.journey-rail');if(rail)rail.outerHTML=progressRail();persist()};
edit=function(k,v){priorEdit(k,v);persist()};
const priorLog=log;log=function(t,id=current){priorLog(t,id);persist()};
choose=function(value){priorChoose(value);if(value==='handoff'&&A().stage==='review'&&current==='economics'){A().copy='Reconcile the campaign funding agreement, product costs and mature refunds before changing rewards. Compare retained contribution by assigned cohort. Preserve all issued rewards. No customer contact or new incentive is authorised.';refreshChat()}};
const coreBudget=budget;budget=function(){return A().choice==='handoff'?0:coreBudget()};
reviewCard=function(){let a=A(),c=C();let summary=`<div class="approval-contract"><div><span>Action</span><strong>${a.choice==='handoff'?'Internal brief only':c.action}</strong></div><div><span>Audience</span><strong>${a.choice==='handoff'?'Merchant team only':a.cap+' maximum assigned'}</strong></div><div><span>Control group</span><strong>${a.choice==='handoff'?'Not applicable':'50% of assigned audience'}</strong></div><div><span>Boundaries</span><strong>${a.choice==='handoff'?'No publication or sends':'One test · No automatic expansion'}</strong></div></div>`;let html=priorReview();if(a.choice==='handoff')html=html.replace(/New variant contribution floor: ₹handoff/g,'Analysis brief only').replace('₹425 per retained order before incremental delivery costs','No reward change authorised').replace('Preview what the customer sees','Preview draft context').replace(c.terms,'Internal review only. Existing customer offers and permissions remain unchanged.').replace(c.capLabel,'Maximum records in brief');return `<div class="approval-intro"><strong>A small, controlled next step</strong><p>Review what changes, who is included and how we will measure it. You can edit the plan or choose not to proceed.</p>${summary}</div>`+html};
stepsFor=function(type){if(type==='investigate')return C().steps;if(A().choice==='handoff')return [['Policy checker','Verify internal-only approval','No customer contact, offer change or publication allowed.'],['Brief agent','Prepare the approved brief','Source notes, unresolved questions and next owner recorded.'],['Verification agent','Confirm the brief is ready','Saved for merchant review. No revenue claim is made.']];let kind=caseKind();return [['Policy checker','Recheck the approved plan and eligibility',kind==='recovery'?'Current paid status, consent, stock where relevant and route health checked.':'Source versions, merchant permission, terms and cap checked.'],['Action agent',kind==='clarity'?'Stage the approved page variant':kind==='cost'?'Create a separate reward variant':'Prepare the capped message schedule',kind==='cost'?'Existing rewards preserved; maximum redemption budget reserved in demo.':'Control assignment and exact approved content recorded in demo.'],['Verification agent','Verify execution and measurement','Simulated provider receipt recorded. Test scheduled with stop controls.']]};
begin=function(type){priorBegin(type);persist()};
doneCard=function(){let a=A();return `<div class="completion-note"><div class="successmark">${icon('check')}</div><div><h3>${a.choice==='handoff'?'Your brief is ready to review':'Your approved plan is ready'}</h3><p>${a.choice==='handoff'?'No customer action was taken. Your team has the context to decide.':'The simulated execution is verified. The audience and budget remain within your approval.'}</p></div></div>`+priorDone()+`<details class="receipt-detail"><summary>View approval and execution receipt</summary><div class="ruleline"><span>Scenario</span><strong>${C().campaign}</strong></div><div class="ruleline"><span>Approved cap</span><strong>${a.approval?.cap||a.cap}</strong></div><div class="ruleline"><span>Maximum incentive budget</span><strong>₹${(a.approval?.budget||0).toLocaleString('en-IN')}</strong></div><p class="fine spaced">Demo receipt · No real provider request. View Activity for the decision history.</p></details>`};
evidence=function(){if(['incident','economics'].includes(current)){let f=FUTURES[current];return `<section class="panel"><div class="eyebrow">Connected investigation</div><h2>Several sources, one reviewable decision</h2><p class="spaced">${f.pain}</p>${sourceBoard(f.evidence)}<h3>What the evidence supports</h3>${f.hypotheses.map(([t,st,why])=>`<div class="hypothesis-row"><div><strong>${t}</strong><small>${st}</small></div><span>${why}</span></div>`).join('')}<p class="spaced">${f.limits}</p><div class="nextbar"><p>Choose the boundary that fits your business, then review the exact intervention.</p>${btn('Discuss with assistant',"switchTab('chat')",'primary')}</div></section>`}return priorEvidence()};
const OUTCOMES={recovery:{metric:'Paid orders / eligible shopper',control:'2 / 19',test:'5 / 19',headline:'A recovery signal, not proof of lift',rows:[['Assigned shoppers','19','19'],['Paid orders','2','5'],['Paid conversion','10.5%','26.3%']],note:'This cohort is too small for a reliable lift conclusion. Net contribution also needs retained-order costs, message costs and refunds.',gain:'Help genuinely unpaid shoppers retry, without messaging those who already paid.',next:'Validate safe execution and design a larger evaluation before claiming recovered revenue.'},cost:{metric:'Contribution / assigned customer',control:'₹70',test:'₹76.50',headline:'More contribution despite fewer orders',rows:[['Assigned customers','100','100'],['Purchase conversion','20%','18%'],['Contribution per retained order','₹350','₹425'],['Contribution per assigned customer','₹70','₹76.50']],note:'20% × ₹350 versus 18% × ₹425, before extra intervention costs. These are constructed figures. Confidence and mature refund data are not established.',gain:'Learn whether a smaller reward can improve profit without changing issued rewards.',next:'Wait for mature costs and refunds. Expand only after evidence supports the result and you approve a new cap.'},repeat:{metric:'Repeat orders / assigned customer',control:'12 / 300',test:'18 / 300',headline:'A more relevant reminder, with a holdout',rows:[['Assigned customers','300','300'],['Repeat orders','12','18'],['Repeat purchase rate','4%','6%'],['Additional discount','₹0','₹0']],note:'Fixed illustrative cohort of 600, independent of edited demo caps. Account for message cost and refunds before claiming contribution lift. Uncertainty remains.',gain:'Encourage repeat purchases while respecting recent buyers, opt-outs and contact limits.',next:'Keep the next audience bounded. Do not turn a small apparent lift into automatic outreach to everyone.'}};
resultTab=function(){if(!A().results||current==='clarity')return priorResults();let o=OUTCOMES[caseKind()],a=A();if(!o)return priorResults();return `<div class="callout">${icon('info')}Illustrative outcome only · Fixed sample comparison, not recalculated from your edited cap. No live revenue or experiment result.</div><div class="metrics">${metric(o.metric+' · Control',o.control,'Original experience / no-message holdout')}${metric(o.metric+' · Test',o.test,'Approved variant in this example')}${metric('Decision','Keep learning','No automatic rollout')}${metric('Your control',a.paused?'Paused':'Review next step','A wider scope requires a new approval')}</div><div class="grid"><section class="panel"><h2>${o.headline}</h2><p class="spaced">${o.gain}</p><table class="table sectionspace"><thead><tr><th>Measure</th><th>Control</th><th>Test</th></tr></thead><tbody>${o.rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="comparebox sectionspace"><h3>Before making the next decision</h3><p>${o.note}</p></div><p class="spaced">${o.next}</p><div class="row spaced">${btn('Review a next plan','revise()','primary')}${btn('Stop future work',"stopWork();switchTab('chat')")}</div></section><aside class="panel"><h3>What we learned</h3><p class="spaced">Record the hypothesis, evidence versions, your edits, assignment, paid outcomes and costs. Update recommendations only with mature, credible evidence.</p><h3 class="spaced">What we still need</h3><p class="spaced">Reliable uncertainty estimates, refund maturity and a sufficiently powered comparison. Your merchant data stays scoped to your business.</p></aside></div>`};
modal=function(type){if(type==='guide'){let dlg=document.createElement('dialog');dlg.className='personal-modal';dlg.setAttribute('aria-label','Explore all six journeys');dlg.innerHTML=`<h2>Six complete journeys</h2><p>Choose any opportunity. Investigate, answer the merchant question, review evidence, edit the plan, preview it and approve. Watch the agent steps, then review a sample outcome and decide what comes next.</p><p>Offer clarity is a good first tour. Payment recovery, incentive efficiency and repeat timing remain fully available. Campaign diagnosis and profit diagnosis extend the same flow across more evidence sources.</p><p>Your demo progress is saved in this browser. A running step pauses safely after a reload. My experiments gathers your work; Reset clears it. All data and actions are simulated.</p><div class="actions">${btn('Got it','closeModal()','primary')}</div>`;$('overlay').replaceChildren(dlg);dlg.showModal();return}priorModal(type)};
const priorAsk=ask;ask=function(t){if(A().stage==='question'&&/wait|hold|internal|no contact/i.test(t)&&['economics','incident'].includes(current)){choose('handoff');return}priorAsk(t)};
resetDemo=function(){cancelAnimationFrame(raf);clearInterval(futureTimer);for(const id of Object.keys(sessions))delete sessions[id];for(const id of Object.keys(futureState))delete futureState[id];try{localStorage.removeItem(STORAGE)}catch(e){}current='clarity';tab='chat';page='overview';render();toast('Demo reset. All six journeys are ready.')};
openFuture=function(id){openCase(id)};
setInterval(persist,1500);
render();
const priorPlan=planTab;
planTab=function(){let a=A();if(a.choice!=='handoff')return priorPlan();return `<section class="panel"><div class="between"><h2>Your internal brief</h2>${pill(a.approved?'Approved brief':'Draft',a.approved?'green':'amber')}</div><p class="spaced">${C().campaign} · No customer publication, message or reward change authorised.</p><div class="comparebox sectionspace"><div class="eyebrow">Approved scope and suggested content</div><p style="white-space:pre-wrap">${safe(a.copy)}</p></div><h3 class="sectionspace">Evidence to include</h3><p class="spaced">${C().finding}</p><h3 class="sectionspace">Next owner and measurement</h3><p class="spaced">You or your authorised team can review the brief. A new approval is required before any customer action. An internal brief alone produces no measurable revenue.</p><div class="row sectionspace">${btn(a.approved?'Edit & reapprove':'Review in assistant',a.approved?'revise()':"switchTab('chat')",'primary')}${a.approved?btn('Download brief','downloadBrief()'):''}</div></section>`};
function downloadBrief(){let text=[C().campaign,'Internal brief — fictional prototype',A().copy,'Evidence: '+C().finding,'No customer publication, contact or financial change authorised.'].join('\n\n');let url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));let a=document.createElement('a');a.href=url;a.download='campaign-investigation-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);log('Merchant downloaded the internal brief.');toast('Brief downloaded. No customer action taken.')}
render();
